package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ZipArchiveEntry_setName_TriageGen2Test {

    @Test
    public void testSetNameNormal() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("originalName");
        String newName = "newName.txt";

        // Since setName is protected, we use reflection to access it
        Method setNameMethod = ZipArchiveEntry.class.getDeclaredMethod("setName", String.class);
        setNameMethod.setAccessible(true);

        setNameMethod.invoke(entry, newName);

        assertEquals("The name should be updated to the new value", newName, entry.getName());
    }

    @Test
    public void testSetNameNull() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("originalName");

        Method setNameMethod = ZipArchiveEntry.class.getDeclaredMethod("setName", String.class);
        setNameMethod.setAccessible(true);

        setNameMethod.invoke(entry, (String) null);

        assertEquals("The name should be null after setting it to null", null, entry.getName());
    }

    @Test
    public void testSetNameEmpty() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("originalName");
        String emptyName = "";

        Method setNameMethod = ZipArchiveEntry.class.getDeclaredMethod("setName", String.class);
        setNameMethod.setAccessible(true);

        setNameMethod.invoke(entry, emptyName);

        assertEquals("The name should be empty", emptyName, entry.getName());
    }

    @Test
    public void testSetNameWithSpecialCharacters() throws Exception {
        ZipArchiveEntry entry = new ZipArchiveEntry("old");
        String specialName = "folder/subfolder/file!@#$%^&()*.txt";

        Method setNameMethod = ZipArchiveEntry.class.getDeclaredMethod("setName", String.class);
        setNameMethod.setAccessible(true);

        setNameMethod.invoke(entry, specialName);

        assertEquals("The name should handle special characters", specialName, entry.getName());
    }
}
